"use client";
// @zeus-internal
import { useEffect, useRef, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { ArtemisButton } from "../../../../foundations/button";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
import { demoResponse, type AgentConfiguration } from "./data";
type Message = {
    id: number;
    role: "user" | "assistant";
    content: string;
};
export function AgentChat({ config }: {
    config: AgentConfiguration;
}) {
    const [messages, setMessages] = useState<Message[]>([]);
    const [draft, setDraft] = useState("");
    const nextId = useRef(0);
    const logRef = useRef<HTMLDivElement>(null);
    const reduce = useReducedMotion();
    const send = (value: string) => { const question = value.trim(); if (!question)
        return; setDraft(""); const user: Message = { id: ++nextId.current, role: "user", content: question }; const answer: Message = { id: ++nextId.current, role: "assistant", content: demoResponse(config, question) }; setMessages(previous => [...previous, user, answer]); };
    useEffect(() => { if (logRef.current)
        logRef.current.scrollTop = logRef.current.scrollHeight; }, [messages]);
    return (<section className="art:flex art:min-h-[32rem] art:flex-col art:rounded-2xl art:border art:border-border art:bg-background art:p-4 art:@min-[640px]/artemis:p-5 art:@min-[1024px]/artemis:h-full" aria-label="Agent test chat">
              <header className="art:flex art:items-center art:justify-between art:gap-3 art:px-1 art:pb-4">
