                  </div>
                </div>
                <ArtemisButton type="button" variant="ghost" size="icon" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9 art:rounded-full" aria-label="Reset test conversation" title="Reset conversation" disabled={!messages.length} onClick={() => setMessages([])} tabIndex={0}>
                  <svg xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-rotate-ccw" aria-hidden="true">
                    <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/>
                    <path d="M3 3v5h5"/>
                  </svg>
                </ArtemisButton>
              </header>
              <div className="art:min-h-0 art:max-h-96 art:flex-1 art:space-y-5 art:overflow-y-auto art:px-1 art:py-5 art:@min-[1024px]/artemis:max-h-[32rem]" ref={logRef} role="log" aria-live="polite" aria-relevant="additions text">
        {messages.length === 0 ? (<div className="art:flex art:min-h-72 art:flex-col art:items-center art:justify-center art:text-center">
                  <span className="art:mb-5 art:flex art:size-14 art:items-center art:justify-center art:rounded-full art:bg-muted">
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-bot" aria-hidden="true">
                      <path d="M12 8V4H8"/>
                      <rect width="16" height="12" x="4" y="8" rx="2"/>
                      <path d="M2 14h2"/>
                      <path d="M20 14h2"/>
                      <path d="M15 13v2"/>
                      <path d="M9 13v2"/>
                    </svg>
                  </span>
                  <h3 className="art:text-xl art:font-medium">
                    {"Meet "}
                    {config.name || "your agent"}
                  </h3>
                  <p className="art:mt-3 art:max-w-xs art:text-sm art:leading-relaxed art:text-muted-foreground">
                    {"Try a real question. Refine your instructions, then test again."}
                  </p>
                  <div className="art:mt-6 art:flex art:flex-wrap art:justify-center art:gap-2">
                    <ArtemisButton type="button" variant="ghost" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:text-foreground art:gap-2 art:px-5 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:bg-muted art:text-xs art:hover:bg-muted/80 art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9 art:rounded-full" tabIndex={0} onClick={() => send("What can you help me with?")}>
