                    </ArtemisButton>
                    <ArtemisButton type="button" variant="ghost" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:text-foreground art:gap-2 art:px-5 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:bg-muted art:text-xs art:hover:bg-muted/80 art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9 art:rounded-full" tabIndex={0} onClick={() => send("How do I invite a teammate?")}>
