        {message.role === "user" ? <><span className="art:sr-only">You:</span><p className="art:whitespace-pre-wrap art:break-words art:text-sm art:leading-6">{message.content}</p></> : <><p className="art:mb-2 art:text-xs art:font-medium art:text-muted-foreground">{config.name || "Agent"}</p><p className="art:whitespace-pre-wrap art:break-words art:text-sm art:leading-6">{message.content}</p></>}
        </motion.div>)}
              </div>
              <div className="art:pt-4">
                <div className="art:mb-3 art:flex art:items-center art:justify-between art:gap-3">
                  <p role="alert" className="art:text-xs art:text-destructive">
                    {" "}
                  </p>
                  <ArtemisButton type="button" variant="ghost" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:gap-2 art:px-5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:text-xs art:h-9 art:rounded-full" tabIndex={0}>
                    {"Retry"}
                  </ArtemisButton>
                </div>
                <div className="art:rounded-2xl art:border art:border-border art:p-3 art:focus-within:ring-2 art:focus-within:ring-ring">
                  <textarea value={draft} onChange={e => setDraft(e.target.value)} onKeyDown={e => { if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
        e.preventDefault();
        send(draft);
    } }} aria-label="Test message" placeholder="Ask a test question…" rows={2} className="art:block art:max-h-40 art:min-h-12 art:w-full art:resize-none art:bg-transparent art:px-1 art:py-1 art:text-sm art:leading-6 art:text-foreground art:outline-none art:placeholder:text-muted-foreground art:disabled:cursor-not-allowed art:disabled:opacity-60"/>
                  <div className="art:mt-2 art:flex art:items-center art:justify-between art:gap-3">
                    <p className="art:text-xs art:text-muted-foreground">
                      {config.sourceIds.length}
                      {" "}
                      {config.sourceIds.length === 1 ? "source" : "sources"}
                      {" \u00B7"}
                      {" "}
                      {config.toolIds.length}
                      {" "}
                      {config.toolIds.length === 1 ? "tool" : "tools"}
                    </p>
                    <ArtemisButton type="button" variant="primary" size="icon" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9 art:rounded-full" aria-label="Send test message" disabled={!draft.trim()} onClick={() => send(draft)} tabIndex={0}>
                      <svg xmlns="http://www.w3.org/2000/svg" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up" aria-hidden="true">
                        <path d="m5 12 7-7 7 7"/>
                        <path d="M12 19V5"/>
                      </svg>
                    </ArtemisButton>
                  </div>
                </div>
              </div>
            </section>);
}

