// @zeus-internal
import type { AgentModel } from "./model-select";
export type AgentConfiguration = {
    name: string;
    description: string;
    model: AgentModel;
    instructions: string;
    sourceIds: string[];
    toolIds: string[];
    requireApproval: boolean;
};
export const INITIAL: AgentConfiguration = { name: "Customer support", description: "Clear answers. Thoughtful follow-ups.", model: "Balanced", instructions: "You are a helpful customer support assistant. Answer using the connected knowledge sources. Keep responses clear and concise. If you cannot verify an answer, say so and suggest contacting the support team. Ask for approval before taking actions that change customer data.", sourceIds: ["help", "handbook"], toolIds: ["search"], requireApproval: true };
export function demoResponse(config: AgentConfiguration, question: string): string {
    if (!config.sourceIds.length)
        return "Demo response: no knowledge sources are selected. Enable a source in the Knowledge tab to give this agent some context.";
    if (question.toLowerCase().includes("invite"))
        return "Demo response: open Settings \u2192 Team, enter your teammate\u2019s email, and choose their role. Review the details before sending the invitation.\n\nThis sample answer is prewritten; no model or external tool was called.";
    return `Demo response: I\u2019m ${config.name}. I can help answer questions using ${config.sourceIds.length} selected knowledge sources. ${config.requireApproval ? "I\u2019ll ask before taking actions that change data." : "Action approval is currently disabled in this configuration."}

This is a prewritten preview response. Connect your own test handler for live answers.`;
}

"use client";
