"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "./ease";
export function ArtemisCheckMark({ selected, mixed = false }: { selected: boolean; mixed?: boolean }) {
  const reduce = useReducedMotion();
  return <AnimatePresence initial={false}>{selected && <motion.svg key={mixed ? "mixed" : "check"} width={12} height={12} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" initial={reduce ? false : { opacity: 0, scale: 0.5 }} animate={{ opacity: 1, scale: 1 }} exit={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.5, filter: "blur(4px)" }} transition={{ duration: reduce ? 0 : 0.16, ease: ARTEMIS_EASE_OUT }}><motion.path d={mixed ? "M6 12H18" : "M5 13L9 17L19 7"} pathLength={1} initial={reduce ? false : { pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ duration: reduce ? 0 : mixed ? 0.2 : 0.3, delay: reduce ? 0 : 0.04, ease: ARTEMIS_EASE_OUT }}/></motion.svg>}</AnimatePresence>;
}

"use client";
// @zeus-internal
import { useId } from "react";
import { ArtemisPressButton } from "./press-button";
import { ArtemisCheckMark } from "./check-mark";
import { artemisCx } from "./utils";
export interface CheckboxProps { checked: boolean; onCheckedChange: (checked: boolean) => void; disabled?: boolean; indeterminate?: boolean; label?: string; description?: string; className?: string; id?: string; "aria-label"?: string; "aria-describedby"?: string; }
export function Checkbox({ checked, onCheckedChange, disabled, indeterminate, label, description, className, id: givenId, "aria-label": ariaLabel, "aria-describedby": describedBy }: CheckboxProps) {
  const unique = useId(), id = givenId ?? unique;
  const selected = checked || !!indeterminate;
  const descriptionId = description ? `${id}-description` : undefined;
  return <label htmlFor={id} className={artemisCx("art:inline-flex art:gap-3", description ? "art:items-start" : "art:items-center", disabled ? "art:cursor-not-allowed" : "art:cursor-pointer", className)}>
    <ArtemisPressButton hoverScale={null} pressScale={0.92} id={id} type="button" role="checkbox" aria-checked={indeterminate ? "mixed" : checked} aria-label={ariaLabel} aria-labelledby={!ariaLabel && label ? `${id}-label` : undefined} aria-describedby={[describedBy, descriptionId].filter(Boolean).join(" ") || undefined} data-state={indeterminate ? "indeterminate" : checked ? "checked" : "unchecked"} disabled={disabled} onClick={() => onCheckedChange(!checked)} className={artemisCx("art:inline-flex art:h-5 art:w-5 art:shrink-0 art:items-center art:justify-center art:rounded-md art:border-2 art:outline-none art:transition-colors art:duration-200 art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:disabled:cursor-not-allowed art:disabled:opacity-60", selected ? "art:border-primary art:bg-primary art:text-primary-foreground" : "art:border-muted-foreground/50 art:bg-background art:hover:border-muted-foreground")}><ArtemisCheckMark selected={selected} mixed={indeterminate}/></ArtemisPressButton>
    {(label || description) && <span className="art:flex art:min-w-0 art:flex-col art:gap-0.5"><span id={`${id}-label`} className={artemisCx("art:text-sm art:text-foreground",description && "art:leading-4")}>{label}</span>{description && <span id={descriptionId} className="art:text-xs art:text-muted-foreground">{description}</span>}</span>}
  </label>;
}

export { Checkbox as ArtemisCheckbox };

"use client";
// @zeus-internal
import { motion, useReducedMotion, type HTMLMotionProps } from "motion/react";
import { ARTEMIS_SPRING_PRESS } from "./ease";
export function ArtemisPressButton({ pressScale = 0.99, hoverScale = 1.01, ...props }: HTMLMotionProps<"button"> & { pressScale?: number | null; hoverScale?: number | null }) {
  const still = useReducedMotion() === true;
  return <motion.button {...props} whileHover={still || hoverScale === null || props.disabled ? undefined : { scale: hoverScale }} whileTap={still || pressScale === null || props.disabled ? undefined : { scale: pressScale }} transition={ARTEMIS_SPRING_PRESS}/>;
}

"use client";
// @zeus-internal
import { animate, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState, type HTMLAttributes } from "react";
export interface ArtemisValidationFrameProps extends HTMLAttributes<HTMLDivElement> {
    error?: boolean;
    focused?: boolean;
    focusBorder?: string;
    finishShakeOnClear?: boolean;
}
export function ArtemisValidationFrame({ error = false, focused: controlled, focusBorder = "art:border-foreground/60", finishShakeOnClear = true, className = "", children, onFocus, onBlur, ...props }: ArtemisValidationFrameProps) {
    const [focus, setFocus] = useState(false);
    const ref = useRef<HTMLDivElement>(null);
    const reduce = useReducedMotion();
    const playbackRef = useRef<{
        stop: () => void;
    } | null>(null);
    useEffect(() => () => playbackRef.current?.stop(), []);
    const focused = controlled ?? focus;
    useEffect(() => {
        const element = ref.current;
        if (!element || !error || reduce) {
            if (element && (reduce || !finishShakeOnClear)) {
                playbackRef.current?.stop();
                playbackRef.current = null;
                element.style.transform = "none";
                element.style.translate = "none";
            }
            return;
        }
        playbackRef.current?.stop();
        const playback = animate(element, { x: [0, -6, 6, -4, 4, -2, 0] }, { duration: 0.45 });
        playbackRef.current = playback;
        return () => { if (!finishShakeOnClear) {
            playback.stop();
            if (playbackRef.current === playback)
                playbackRef.current = null;
        } };
    }, [error, reduce, finishShakeOnClear]);
    const border = error ? "art:border-destructive" : focused ? focusBorder : "art:border-border";
    return <div {...props} ref={ref} data-state={error ? "error" : focused ? "focused" : "idle"} className={`art:relative art:h-10 art:overflow-hidden art:rounded-full art:border art:bg-background art:transition-colors art:duration-200 ${border} ${className}`} onFocus={event => { setFocus(true); onFocus?.(event); }} onBlur={event => { if (!event.currentTarget.contains(event.relatedTarget))
        setFocus(false); onBlur?.(event); }}>{children}</div>;
}
